window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e8658e05541a02c1"]={"versions": [{"id": "FIG-e8658e05541a02c1", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architekturdiagramm zur Veranschaulichung des Schichtenmodells und Signalflusses bei der Alive-Überwachung (Alive-Supervision) einer einzelnen Entität im AUTOSAR-Classic-Stack (Spezifikation des Watchdog Managers). Das Diagramm stellt die vertikale Integration von der Anwendungsebene über die RTE, den Watchdog Manager (Wdm) und das Watchdog Interface (WdgIf) bis hin zu Treibern und Hardware dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>application software ( = SE (1) )</strong>: Oberste Ebene, agiert als einzelne überwachte Entität (Supervised Entity 1).\n</li><li><strong>RTE (Runtime Environment)</strong>: Horizontale Middleware-Schicht mit Port-Verbindung; enthält einen P-Port zur Alive-Signalisierung („P-Port for alive indication from whole application software ( = 1 supervised entity )“).\n</li><li><strong>Watchdog Manager (Wdm)</strong>: Zentrales BSW-Modul (hervorgehoben), enthält den Alive-Counter/Port-Endpunkt „AC (SE1)“ und führt den internen Zustand „global supervision status = check enabled“.\n</li><li><strong>Watchdog Interface (WdgIf)</strong>: BSW-Abstraktionsschicht, angesprochen über eine standardisierte Schnittstelle („use standardized interface for watchdog-triggering“).\n</li><li><strong>Watchdog Driver (Wdg)</strong>: MCAL- bzw. BSW-Treiberschicht; links ein Treiber für „internal Watchdog-HW“, rechts optional/beispielhaft gestrichelt ein weiterer Treiber für „i.e. external Watchdog-HW“ („i.e. of multiple Watchdog-HW“).\n</li><li><strong>HW</strong>: Unterste Schicht (Hardware-Ebene), unterteilt in interne Watchdog-Hardware und externe Watchdog-Hardware.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Anwendungssoftware signalisiert ihre Aktivität („alive indication“) zyklisch oder ereignisbasiert über einen P-Port an die RTE.\n</li><li>Die RTE leitet die Alive-Meldung an den Alive-Counter-Eingang <code>AC (SE1)</code> des Watchdog Managers weiter.\n</li><li>Der Watchdog Manager prüft die Alive-Indikationen anhand der konfigurierten Zyklengrenzen; bei aktivem Überwachungszustand („global supervision status = check enabled“) wird das Watchdog-Triggern autorisiert.\n</li><li>Der Watchdog Manager bedient die standardisierte Schnittstelle des Watchdog Interface („use standardized interface for watchdog-triggering“).\n</li><li>Das Watchdog Interface leitet die Trigger-Befehle an den internen Watchdog-Treiber und optional an externe Watchdog-Treiber weiter, welche letztlich die physische Watchdog-Hardware bedienen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Bildet den Basisfall der Alive-Überwachung für genau eine Supervised Entity über die RTE ab.\n</li><li>Zeigt die Pflicht zur Nutzung der standardisierten Schnittstelle zwischen Watchdog Manager und Watchdog Interface zur Hardware-Triggerung.\n</li><li>Verdeutlicht das Architekturmuster zur Ansteuerung mehrerer Watchdog-Instanzen (interner sowie externer Watchdog) über separate Treiberinstanzen hinter einem einheitlichen Watchdog Interface.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-225ac92f8113a092", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architekturdiagramm zur Veranschaulichung des Schichtenmodells und Signalflusses bei der Alive-Überwachung (Alive-Supervision) einer einzelnen Entität im AUTOSAR-Classic-Stack (Spezifikation des Watchdog Managers). Das Diagramm stellt die vertikale Integration von der Anwendungsebene über die RTE, den Watchdog Manager (Wdm) und das Watchdog Interface (WdgIf) bis hin zu Treibern und Hardware dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>application software ( = SE (1) )</strong>: Oberste Ebene, agiert als einzelne überwachte Entität (Supervised Entity 1).\n</li><li><strong>RTE (Runtime Environment)</strong>: Horizontale Middleware-Schicht mit Port-Verbindung; enthält einen P-Port zur Alive-Signalisierung („P-Port for alive indication from whole application software ( = 1 supervised entity )“).\n</li><li><strong>Watchdog Manager (Wdm)</strong>: Zentrales BSW-Modul (hervorgehoben), enthält den Alive-Counter/Port-Endpunkt „AC (SE1)“ und führt den internen Zustand „global supervision status = check enabled“.\n</li><li><strong>Watchdog Interface (WdgIf)</strong>: BSW-Abstraktionsschicht, angesprochen über eine standardisierte Schnittstelle („use standardized interface for watchdog-triggering“).\n</li><li><strong>Watchdog Driver (Wdg)</strong>: MCAL- bzw. BSW-Treiberschicht; links ein Treiber für „internal Watchdog-HW“, rechts optional/beispielhaft gestrichelt ein weiterer Treiber für „i.e. external Watchdog-HW“ („i.e. of multiple Watchdog-HW“).\n</li><li><strong>HW</strong>: Unterste Schicht (Hardware-Ebene), unterteilt in interne Watchdog-Hardware und externe Watchdog-Hardware.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Anwendungssoftware signalisiert ihre Aktivität („alive indication“) zyklisch oder ereignisbasiert über einen P-Port an die RTE.\n</li><li>Die RTE leitet die Alive-Meldung an den Alive-Counter-Eingang <code>AC (SE1)</code> des Watchdog Managers weiter.\n</li><li>Der Watchdog Manager prüft die Alive-Indikationen anhand der konfigurierten Zyklengrenzen; bei aktivem Überwachungszustand („global supervision status = check enabled“) wird das Watchdog-Triggern autorisiert.\n</li><li>Der Watchdog Manager bedient die standardisierte Schnittstelle des Watchdog Interface („use standardized interface for watchdog-triggering“).\n</li><li>Das Watchdog Interface leitet die Trigger-Befehle an den internen Watchdog-Treiber und optional an externe Watchdog-Treiber weiter, welche letztlich die physische Watchdog-Hardware bedienen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Bildet den Basisfall der Alive-Überwachung für genau eine Supervised Entity über die RTE ab.\n</li><li>Zeigt die Pflicht zur Nutzung der standardisierten Schnittstelle zwischen Watchdog Manager und Watchdog Interface zur Hardware-Triggerung.\n</li><li>Verdeutlicht das Architekturmuster zur Ansteuerung mehrerer Watchdog-Instanzen (interner sowie externer Watchdog) über separate Treiberinstanzen hinter einem einheitlichen Watchdog Interface.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-e8658e05541a02c1", "to": "FIG-225ac92f8113a092", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
